#!/usr/bin/env python3
"""Guarded clarity migration for the six remaining decks; originals stay in Git."""
import argparse, hashlib, html, json, re, subprocess
from pathlib import Path
import apply_batch2 as eng
ROOT=eng.ROOT; HERE=eng.HERE; BASE=eng.BASE
slide=eng.slide; cards=eng.cards; code=eng.code; bul=eng.bul; table=eng.table; notes=eng.notes; sha=eng.sha
outputs={}; maps={}; metrics={}; originals={}
CACHE='https://platform.claude.com/docs/en/build-with-claude/prompt-caching'
SKILLS='https://code.claude.com/docs/en/skills'
SUB='https://code.claude.com/docs/en/sub-agents'
EVAL='https://www.anthropic.com/engineering/demystifying-evals-for-ai-agents'
CONTEXT='https://www.anthropic.com/engineering/effective-context-engineering-for-ai-agents'
MCP='https://modelcontextprotocol.io/docs/learn/architecture'
def link(url,label): return f'<a href="{url}">{label}</a>'
def s(label,title,content,note,speaker,theme='light',tag='In practice'):return slide(label,title,content,note,speaker,theme,tag)
def cover(title,subtitle,audience):
 return f'''<section class="slide dark title-slide" data-label="Title" data-speaker-notes="{eng.esc(audience+' Revised October 2026. Worked examples are illustrative; no live run is required.')}" ><div class="ts-top"><span class="k">{audience}</span><span class="meta">Revised October 2026</span></div><div class="ts-hero"><h1>{title}<span class="dot">.</span></h1><p class="ts-sub">{subtitle}</p></div><div class="ts-foot"><div class="ts-author">David Budáč</div></div></section>'''
def sources(items,note='Primary documentation checked 3 October 2026. Examples are illustrative unless explicitly attributed.'):
 return s('Sources','Sources and further reading',bul([link(u,l) for l,u in items]),note,'Leave the sources visible for questions. These links support the mechanisms and qualifications; the examples are teaching material, not benchmark measurements.',theme='dark',tag='Sources')
def build(name,title,main,ref,groups=None,shell=None):
 original=subprocess.check_output(['git','show',BASE+':'+name+'.html'],cwd=ROOT,text=True); originals[name]=original
 if name=='subagents-prompt-caching':
  decoded=json.loads(re.search(r'<script type="__bundler/template">\s*(.*?)\s*</script>',original,re.S)[1]); old=eng.SECTION.findall(decoded)
 else:old=eng.SECTION.findall(original)
 shell=shell or original; m=re.search(r'(<deck-stage\b[^>]*>)(.*?)(</deck-stage>)',shell,re.S);assert m
 def wrap(items,reference=False):
  prepared=[]
  for n,(origin,content) in enumerate(items,1):
   content=eng.prepare(content,origin,n)
   if reference:content=re.sub(r'(<section\b[^>]*>)',lambda x:x[1]+f'<div class="reference-banner">Optional reference · {link(name+".html","Back to the talk")}</div>',content,count=1)
   prepared.append(content)
  out=shell[:m.start(2)]+'\n\n'+'\n\n'.join(prepared)+'\n\n'+shell[m.end(2):]
  out=re.sub(r'<title>.*?</title>',lambda _:f'<title>{html.escape(title)}'+(' — Reference' if reference else '')+'</title>',out,count=1)
  out=re.sub(r'<!--\s*=+.*?-->', '<!-- Revised clarity teaching path; see reviews/2026-10-03-clarity/. -->',out,flags=re.S)
  out=out.replace('</head>',eng.css+'\n</head>',1)
  out=out.replace('var current = 0, presenter = null, mouseT = null;',"var current = Math.max(0, Array.from(ds.querySelectorAll(':scope > section')).findIndex(function(s){ return s.hasAttribute('data-deck-active'); })), presenter = null, mouseT = null;")
  out=out.replace('<html>','<html lang="en">')
  return out
 if ref:
  # Add reference access to the penultimate main slide, preserving its notes.
  i,c=main[-2]; c=c.replace('</div></section>',f'<p class="note">{link(name+"-reference.html","Optional reference material")}</p></div></section>'); main[-2]=(i,c)
  rcover=cover(title+'<br>Reference','Supporting procedures and worksheets. '+link(name+'.html','Return to the main talk'),'Optional reference')
  outputs[name+'-reference.html']=wrap([(0,rcover)]+ref,True)
 outputs[name+'.html']=wrap(main)
 groups=groups or {}
 mapping=[]
 for i,x in enumerate(old,1):
  label=html.unescape(re.search(r'data-label="([^"]*)"',x)[1]);mainpos=next((n for n,(j,_) in enumerate(main,1) if j==i),None);refpos=next((n for n,(j,_) in enumerate(ref,2) if j==i),None)
  mapping.append({'original':i,'label':label,'main':mainpos,'reference':refpos,'action':'rewritten' if mainpos or refpos else 'merged/removed','reason':groups.get(i,'Revised teaching example.' if mainpos else 'Optional supporting material.' if refpos else 'Repeated transition or secondary catalogue removed; original retained in baseline Git.')})
 maps[name]=mapping;metrics[name]={'before_slides':len(old),'after_slides':len(main),'reference_slides':len(ref)+1 if ref else 0}

# SUBAGENTS: one architecture map; one lifecycle; one cache example.
sub={}
sub[1]=cover('Subagents &amp;<br>Prompt Caching','Separate working contexts. Reuse matching input.','Deep dive · developers and IT admins')
sub[2]=s('Agenda','Two mechanisms, two different outcomes',cards([('Delegation','Separate an investigation and return useful evidence.'),('Caching','Reuse computed work on eligible matching input.')]),'We will follow two helpers investigating an invoice export.','No product tour. First locate the work, then follow what crosses the boundary, then calculate which reuse actually saves money.')
sub[6]=s('Local and cloud map','Where the work happens in this example', '<div class="cards c2 reveal"><div class="tile"><h3 class="k">Your computer</h3><p>Harness<br>Lead + helper loops<br>Local test tools</p></div><div class="tile"><h3 class="k">Provider cloud</h3><p>API endpoint<br>Model inference<br>Provider prompt cache</p></div></div><p class="lead reveal" style="text-align:center">request → network → response</p>', 'Example topology: a local harness calling a hosted model. Harnesses and tools can also run remotely.', 'Preserve the local-versus-cloud distinction from the original map. The harness coordinates helpers; the provider processes requests. Do not infer that no local state exists just because this prompt cache lives at the provider.',tag='Architecture')
sub[7]=eng.e[36]
sub[9]=s('Delegation lifecycle','Delegate → investigate → return → integrate',cards([('Delegate','Task, inputs, limits and expected return.'),('Investigate','Helper uses tools within its own working context.'),('Integrate','Lead checks the returned evidence and resolves conflicts.')]),'These are lifecycle steps. The investigation is not a network crossing.','The previous four-crossings label mixed message transfers and local steps. A harness can expose helper transcripts or messaging; visibility is a product choice. Separate contexts do not imply separate filesystem permissions.',theme='dark')
sub[10]=s('Fresh or forked','Choose what the helper inherits',table(['Fresh helper','Conversation fork'],[['Task prompt plus its configured instructions and tools.','Existing conversation and configured environment.'],['Provide the invoice rule and paths explicitly.','Useful when the background is expensive to restate.']]),'In both cases, specify scope and the evidence to return. '+link(SUB,'Claude Code subagents and forks'),'Do not describe a fresh helper as literally empty or a fork as isolated from parent input. The exact inheritance and model controls are harness specific.')
sub[11]=s('Return contract','Ask for an answer you can inspect',code('TASK: locate invoice VAT and CSV formatting paths.\nRETURN:\n- finding + file and line reference\n- relevant test or observed output\n- uncertainty and missing evidence\n- suggested next check\nSCOPE: read-only investigation; do not change files.'),'A short unsupported conclusion saves tokens by discarding the part you need.','This is an illustrative delegation prompt. Keep factual evidence and uncertainty in the return. The lead still verifies the findings before relying on them.',theme='dark')
sub[12]=s('Parallel work','Parallelize independent investigations',cards([('Helper A','Locate VAT calculation and its tests.'),('Helper B','Locate CSV formatting and escaping tests.'),('Lead','Resolve the shared contract and own the final patch.')]),'Independent reads can overlap. Edits need ownership and an integration step.','Other architectures may allow direct helper messaging or shared state. Define that coordination explicitly rather than claiming all helpers are mutually invisible.')
sub[14]=s('Delegation economics','Count the setup and the review',cards([('Potential benefit','Less raw investigation in the lead context; shorter elapsed time for independent work.'),('Additional work','Helper input, generated output, coordination and checking the returned findings.')]),'Delegation can be worthwhile without being cheaper. Compare accepted outcomes.','Avoid the claim that a deep task automatically pays for itself. A trivial lookup often does not justify the coordination, but measure the relevant workflow.',theme='dark')
sub[16]=s('Call versus agent','One model call is not a tool-using helper loop',code('PSEUDOCODE\ncontext = task + configured_instructions\nwhile budget_remains:\n    response = model(context)\n    if response.requests_tools:\n        context += permitted_tool_results(response)\n    else:\n        return structured_findings(response)\nreturn incomplete_report()'),'Handle errors, multiple content blocks and stop reasons in real code.','The original messages.create example made one request and selected the last text block. That does not implement multi-turn tool use, nor ensure a text-only return. This sketch states the missing loop without pretending to be an SDK implementation.')
sub[17]=s('Illustrative helper return','A compact trace still needs evidence',code('ILLUSTRATIVE — not a recorded Claude Code session\n\nLead: investigate invoice calculation and export.\nHelper A: calc.py applies no VAT; see invoice rule.\nHelper B: export.py writes the calculated total unchanged.\nLead: verify those findings, then plan one scoped patch.'),'Tool counts, timings and costs should come from a real run if you quote them.','Replace the invented precise transcript statistics. The claim here is how to read the returned evidence, not that the helper has proven the bug.',theme='dark')
sub[22]=eng.e[32]
sub[25]=s('Shared prefix example','Keep the shared material before the questions',code('Shared eligible prefix\n  tools + stable instructions + invoice schema\n\nRequest A: Where is VAT applied?\nRequest B: Where is CSV escaping handled?\n\nChanging the question need not change the shared prefix.'),'A matching prefix must be eligible and already cached; stable text alone does not create a hit. '+link(CACHE,'Caching docs'),'For this Claude example, tools precede system content, then messages. Breakpoints determine writes. Avoid timestamps or changing task text inside the intended shared prefix.')
sub[27]=eng.e[29]
sub[28]=eng.e[33]
sub[29]=s('Cache lifetime','Reuse depends on a live, eligible entry',bul(['Claude documents a default five-minute cache lifetime and an optional one-hour lifetime.','A use refreshes the lifetime from the request start; generation time counts against it.','Minimum prefix length, matching, platform support and writes also determine hits.']),'Check the usage fields and current configuration. '+link(CACHE,'Provider caching documentation'),'Scoped to Claude documentation checked 3 October 2026. Do not generalize TTL rules to all model APIs. A short idle gap can still miss if the preceding response took most of the lifetime.',theme='dark')
sub[31]=s('Verify cache usage','Look for what was read and written',table(['Usage record','Meaning'],[['cache_creation_input_tokens','New content written to the prompt cache.'],['cache_read_input_tokens','Input reused from a cache entry.'],['Uncached input and output','Additional work outside that cached read.']]),'Zeros are a diagnostic clue, not proof of why the cache missed. Compare complete task cost.','Field names here are Claude API examples. Read the exact provider response schema; do not assume token totals exclude or include cache categories the same way across APIs. No measured readout is implied.')
sub[33]=s('Warm-up before fan-out','Concurrent requests do not guarantee shared hits',code('1. Prepare one eligible prefix and matching cache settings.\n2. Start a request that writes that prefix.\n3. Wait until its response begins and the entry is available.\n4. Send matching helper requests; inspect cache usage.'),'Cold simultaneous requests can duplicate cache writes. '+link(CACHE,'Claude cache limits'),'Reuse also depends on cache scope, identity, model and prefix eligibility. A generic fresh helper may have different instructions and tools from its siblings. Do not assume one shared cache across every agent.',theme='dark')
sub[35]=s('Choose authentication','Choose the supported client and credential path',cards([('Native Claude Code use','Sign in through the official flow under the applicable plan and usage rules.'),('Your product or service','Use API-key authentication or a supported cloud-provider route.')]),'The boundary is not simply “human at keyboard” versus “automation”. '+link('https://code.claude.com/docs/en/legal-and-compliance','Current authentication guidance'),'Documentation checked 3 October 2026. Native-client use remains subject to plan limits and agreements. Do not extract, collect or relay subscription credentials into a custom client. This slide summarizes the documented paths; it does not grant blanket approval for all unattended use.')
sub[38]=s('Takeaways','Separate investigation. Verify reuse.',bul(['Give helpers explicit inputs and require evidence in the return.','Separate working contexts do not enforce filesystem or network isolation.','Warm eligible shared prefixes and inspect actual cache reads and writes.']),'Delegation changes where work accumulates. Caching changes the processing cost of repeated input.','Closing correction: caching does not reduce the lead context size or improve information relevance by itself.',theme='dark')
sub[39]=sources([('Subagents and forks',SUB),('Prompt caching and usage',CACHE),('Authentication and usage terms','https://code.claude.com/docs/en/legal-and-compliance')])
subref=[(23,s('Cache block','A cache marker is not a cache guarantee',code('{\n  "type": "text",\n  "text": "stable invoice rules and schema",\n  "cache_control": {"type": "ephemeral"}\n}'),'Claude block example. Eligibility, placement, earlier writes and lifetime still matter.','Valid JSON example with no inline comment. Place the marker using the current API rules and inspect actual usage; the short text displayed alone is below many model minimums.')),(30,s('Multiple breakpoints','Place breakpoints around real reuse',bul(['Mark stable boundaries that requests actually share.','A later change can preserve an earlier cached entry if a write exists there.','Do not assume lookup creates earlier entries that were never written.']),'See '+link(CACHE,'the current lookup and breakpoint limits')+'.','The original implied stable earlier blocks always hit. Reuse requires stored entries and a supported lookup path, not just unchanged text.')),(36,sub[35])]
build('subagents-prompt-caching','Subagents & Prompt Caching',list(sub.items()),subref,{4:'Helper analogy consolidated into main 3–4.',5:'Repeated clean-desk explanation consolidated into delegation example.',8:'Removed unmeasured permanent-clutter figures; main explains scoped history.',13:'Universal no-messaging claim removed; integration taught with parallel roles.',19:'Repeated cache analogy merged into shared-prefix example.',20:'Exact-prefix condition taught beside cache example.',21:'Local/cloud map consolidated into main 3.',24:'Exact-match condition merged with main cache example.',26:'Lookup detail consolidated into usage and reference breakpoints.',32:'Invented cost transcript removed; inspect real usage in main.',34:'Subscription divider removed.',37:'Credential paths and limits reconciled into main authentication slide.'},shell=eng.original)

# COST & CONTEXT: a worked bill and a before/after exercise, no fabricated trace.
cost={1:cover('Cost &amp; Context','Measure a whole task. Keep the information that helps it finish.','Deep dive · developers'),2:s('Agenda','Make one change you can measure',cards([('Cost','Separate billing categories and choose a suitable access route.'),('Context','Trim repeated instructions without losing behavior.'),('Exercise','Compare correctness as well as tokens.')]),'Use the invoice task throughout. No paid live run is required.','Optional live comparison requires a prepared repository, two instruction variants and usage capture. The static exercise works without accounts.'),13:s('Choose the route','Start with how the work will run',table(['Need','Check before choosing'],[['Daily interactive work','Native client, plan limits and actual monthly usage.'],['Custom service, batch or CI','Supported API authentication, rate limits and a budget.'],['Organizational controls','Identity, data handling, audit, residency and procurement requirements.']]),'Compare current offers against these requirements. Detailed shopping questions are in reference material.','Avoid declaring a winner by team size alone. A subscription and an API have different limits and billing; neither guarantees unlimited work.'),4:eng.e[29],5:s('Output cost','High input volume does not identify the largest cost',bul(['Generated output may use a higher token rate than input.','Cached input may be much cheaper than newly processed input.','Reasoning, retries, cache writes and tool fees can change the balance.']),'Use the usage record and elapsed time; a shorter visible answer alone does not prove less computation.','Do not say output always dominates or cost and latency are the same lever. Queues, tools, input processing and generation can all contribute.',theme='dark'),6:eng.e[31],15:eng.e[34],17:eng.e[18],18:eng.e[50],19:s('Instruction file before and after','Shorten the file while preserving its constraints',cards([('Before','Long project history, duplicate style advice, VAT rules, test commands and an old incident log.'),('After','Keep VAT source, rounding rule, test command and schema boundary. Link occasional procedures from a skill.')]),'The acceptance check is unchanged behavior on the same tasks, not the smallest file.','Illustrative transformation. Some easily derived facts can still be useful navigation hints, so do not turn deletion into an absolute rule.'),21:s('Continue or reset','Choose from the state of the task',cards([('Unrelated next task','Start fresh with its own scope and needed project context.'),('Same task, long history','Summarize the goal, evidence, decisions, failed attempts and next check.')]),'Check what survives compaction. Neither a fresh session nor a summary has zero context cost.','Claude Code provides clear and compact commands; consult installed help for current behavior. Do not reset a live task without preserving needed state.',theme='dark'),22:eng.e[36],23:s('Read selectively','Find the relevant span, then enough surrounding context',bul(['Search for the invoice entry point and failing test.','Read the function, its callers and relevant rules before editing.','Delegate broad investigation only when the returned evidence justifies the overhead.']),'A repeated read can be useful after a file changes. Diagnose before calling it waste.','Avoid optimizing raw read counts at the expense of understanding. The appropriate scope depends on the code and the bug.'),24:s('Compare instruction variants','Exercise · compare two versions fairly',code('10 minutes\nA: the long instruction file. B: the shorter version.\nUse identical task inputs, repo state, model and tools.\nRecord: acceptance results, all usage, time and retries.\nRepeat runs if available; inspect failures before choosing.'),'Output: a comparison worksheet and one justified decision. A smaller prompt that drops the VAT rule loses.','An optional live run must use disposable copies and approved credentials. With no runtime, use the next static worksheet and discuss what still needs measurement.',theme='dark'),25:s('Static comparison worksheet','No runtime? Check the proposed rewrite on paper',table(['Requirement','A','B'],[['VAT from order + rounding rule','present','verify preserved'],['Exact invoice test command','present','verify preserved'],['Schema change approval','present','verify preserved'],['Measured task usage and results','not run','not run']]),'Discuss what B removed and which regression case would expose a lost rule. No savings are claimed.','This replaces the empty recorded-run placeholder. Ask participants to identify a measurable acceptance condition for each retained rule. Leave measured fields explicitly not run.'),26:s('Next task','Measure, trim, then verify again',bul(['Record a baseline task outcome and full usage.','Remove one stale or repetitive instruction group.','Repeat the acceptance cases and keep the change only if the tradeoff holds.']),'Keep the task evidence with the instruction change.','Merge the previous two recaps into one action. The outcome may be better clarity, lower cost, both, or neither.',theme='dark'),28:sources([('Context engineering',CONTEXT),('Prompt caching and billing categories',CACHE),('Claude Code usage monitoring','https://code.claude.com/docs/en/monitoring-usage')])}
planref=s('Plan comparison worksheet','Compare current offers using your workload',table(['Record','Question'],[['Price and usage limits','Which work is included, capped or separately billed?'],['Authentication and automation','Does the intended client and deployment use a supported path?'],['Governance','Which retention, identity and audit controls are configured?'],['Actual workload','What is the cost at your observed volume and success rate?']]),'Verify the current plan pages before purchase. '+link('https://claude.com/pricing','Claude plans'),'This replaces volatile price grids and research chatter. It is a worksheet, not a current price audit.')
cloudref=s('Cloud route worksheet','Verify the configured boundary',bul(['Identify the provider, region and any cross-region inference routing.','Confirm the relevant retention, logging and identity settings.','Check model availability, quotas, pricing and your organization’s agreement.']),'A cloud brand alone does not establish residency or prevent data from leaving a region.','This replaces unqualified Bedrock residency and governance claims. The organization must assess its actual endpoints, policies and agreements.',theme='dark')
build('cost-and-context','Cost & Context',list(cost.items()),[(7,planref),(11,cloudref),(20,cost[24])],{8:'Price catalogue replaced by route worksheet.',9:'Subscription/API decision merged into main route choice.',10:'Organizational requirements included in route worksheet.',12:'Product pricing biography removed; use current-offer worksheet.',16:'Repeated context stack merged into request anatomy.',27:'Closing recap merged into original 26.'})

# ORCHESTRATION: a ticket moves through a bounded lifecycle.
orc={1:cover('Orchestrating<br>Agents','Assign work, contain actions and review what returns.','Deep dive · developers'),2:s('Agenda','Follow one invoice ticket to a reviewed patch',cards([('Coordinate','Assign work and resolve ownership.'),('Contain','Set the allowed files, network and runtime budget.'),('Integrate','Check evidence, combine changes and decide whether to accept.')]),'One ticket: export net, VAT and gross invoice values as CSV.','The ticket is illustrative. There is no required issue-tracker account or publishing step.'),4:s('Coordination and containment','Two separate design decisions',cards([('Orchestration','Who gets a task, what it depends on and who integrates the result.'),('Isolation','What files, credentials, processes and network endpoints the tools can access.')]),'A dashboard or Git worktree does not by itself enforce a security boundary.','Preserve the local/environment distinction. Real containment depends on the configured runtime and permissions, not the number of agents.',theme='dark'),15:s('Workflow choice','Choose from the bottleneck',table(['Bottleneck','Useful capability'],[['Too many sessions to track','A monitor with task state and evidence links.'],['Independent changes collide','Separate workspaces plus explicit file ownership.'],['Ready work waits unclaimed','A queue with leases, retries and review gates.'],['Tools can touch too much','A restricted environment with scoped credentials.']]),'Choose products only after these requirements are clear.','This replaces three product biographies and a brand-based decision table. Product examples remain as links in reference.'),7:s('Ticket lifecycle','One ticket, explicit state transitions',code('Ready: invoice rule + scope + acceptance cases\nClaimed: one owner + lease + retry budget\nWorking: permitted workspace + progress evidence\nReview: patch + checks + unresolved gaps\nAccepted: reviewer confirms the requested behavior'),'Failed or blocked work returns with evidence. A green tool run does not automatically publish a change.','A lease or equivalent ownership control prevents duplicate claims. Persist task state. A real integration still needs authentication, idempotency and recovery; this is a teaching lifecycle.'),9:s('Static ticket walkthrough','Walk the invoice ticket without a live service',table(['Event','Expected state or action'],[['Worker finds missing VAT rule','Blocked; request the rule before changing behavior.'],['Two workers claim the same ticket','One claim wins; the other does not start editing.'],['Tests pass but escaping is untested','Review records the gap and adds an acceptance check.']]),'Exercise: explain who owns each decision and what evidence is attached.','Replaces the empty Symphony recording placeholder. This is a tabletop exercise, not a trace from an orchestrator.',theme='dark'),10:s('Tool boundary','Specify the environment the worker receives',bul(['Allow the repository paths and commands required by the ticket.','Scope credentials and network access to the necessary services.','Use separate edit workspaces; enforce time, attempt and spend limits outside the prompt.']),'Review mounts, egress and permissions in the actual runtime.','The old sandbox diagram implied a worktree constrained Git and filesystem access. Make the enforcement mechanism explicit and test it before unattended runs.'),12:eng.e[24],14:s('Review capacity','Limit work in progress to what can be reviewed',cards([('Before starting','Assign the reviewer and agree on the return format.'),('While work runs','Stop filling the queue when review capacity is exhausted.'),('At acceptance','Inspect the integrated result, including interactions between patches.')]),'More workers can move the queue downstream. Measure completed, accepted work.','Do not equate PR count with throughput. A small concurrency limit can outperform unconstrained generation when integration dominates.',theme='dark'),17:eng.e[52],19:s('Rules, procedure and tool','Give each part of the invoice workflow one job',table(['Need','Where it belongs'],[['VAT rate comes from the order','Short project instruction.'],['How to verify an invoice export','Skill with cases and a reporting procedure.'],['Read the invoice specification ticket','An authorized CLI, API or MCP tool.']]),'A procedure teaches how to use access. It does not grant that access.','Keep one example across rules, skills and tools. MCP is an interface option, not a synonym for authentication.'),20:eng.e[57],22:s('Skill exercise','Write a verification skill you can test',code('10 minutes\nDefine the trigger: invoice or CSV export changes.\nWrite four checks: VAT, zero VAT, rounding, escaping.\nName the command and required evidence.\nTest with one matching task and one unrelated task.'),'Output: a small skill file and evidence that it is used when appropriate.','Use the static example next if no agent runtime is available. Do not claim a file was triggered merely because its YAML parses.',theme='dark'),23:eng.e[53],25:s('MCP and CLI','Compare the complete interaction',cards([('MCP','Tools exposed through a client/server protocol, with structured inputs and supported authentication paths.'),('CLI','Commands executed by a shell tool, with help, arguments, output and error handling.')]),'Both can reach local or remote services. Both need appropriate credentials, permissions and review.','Do not equate MCP with remote and CLI with local. A CLI can call a remote service, and an MCP server can run locally.'),28:s('Tool overhead','Definitions are only one part of the cost',bul(['MCP schemas may be loaded eagerly or discovered on demand, depending on the client.','CLI use also consumes shell definitions, help text, command output and repair attempts.','Compare successful completion, tool failures, total usage and latency.']),'Measure the actual client configuration. There is no universal cheaper interface.','Deferred tool loading can change the comparison substantially. Do not claim it is universally opt-in or always enabled.',theme='dark'),30:s('Interface comparison exercise','Run the same read through both interfaces',code('Task: retrieve the invoice ticket and its acceptance cases.\nHold data, access scope and requested output constant.\nFor CLI and MCP, record:\n  correctness; calls; failures; tokens; elapsed time\nRepeat after warm-up; report missing measurements.'),'This is an experiment design, not a completed case study.','Do not manufacture a winning result. If one route lacks the same capability, record that as a capability difference before comparing costs.'),31:s('Next workflow','Design the return and the review before fan-out',bul(['One owner per task and a clear integration point.','Enforced boundaries and a finite retry budget.','Evidence-bearing returns, checked against the original acceptance cases.']),'Choose interface and orchestration tools from observed needs.','Close with the ticket example: the result is a reviewed invoice export, not a busy dashboard.',theme='dark'),32:sources([('MCP architecture',MCP),('Skills',SKILLS),('Subagents and isolation options',SUB),('Claude Code sandboxing','https://code.claude.com/docs/en/sandboxing')])}
orc_ref=s('Tool examples','Evaluate tools against the workflow requirements',bul([link('https://herdr.org','Herdr')+' — inspect monitoring and coordination behavior.',link('https://conductor.build','Conductor')+' — inspect workspace and review behavior.',link('https://github.com/openai/symphony','Symphony')+' — inspect task lifecycle and tracker support.',link('https://github.com/mattpocock/sandcastle','Sandcastle')+' — inspect its configured environment boundary.']),'Reference links, not a current product comparison. Check supported versions and integrations.','The brand biographies were removed from the spoken path. No product is assumed to implement every requirement from the talk.')
build('orchestrating-agents','Orchestrating Agents',list(orc.items()),[(5,orc_ref),(21,eng.e[58]),(29,orc[30])],{6:'Product choice consolidated into reference links.',8:'Live service dependency replaced by static ticket walkthrough.',11:'SDK recipe replaced by concrete boundary requirements.',13:'Conflict handling incorporated into ownership and review controls.',18:'Progressive disclosure consolidated into the invoice skill.',26:'MCP benefits scoped in main comparison.',27:'CLI benefits and overhead scoped in main comparison.'})

# MEASURING: concrete cases, graders, trials and a worksheet.
measure={1:cover('Measuring<br>What Works','Compare outcomes, inspect failures, then change the configuration.','Deep dive · developers'),2:s('Agenda','Evaluate one invoice-export task',cards([('Define','Inputs, expected outcomes and graders.'),('Observe','Repeated trials, tool traces and actual artifacts.'),('Decide','Quality first, then cost, latency and operating constraints.')]),'You can complete the static grading exercise without a model account.','The spoken path prioritizes evaluation. Product catalogues become an optional selection worksheet.'),4:s('What an eval measures','Separate the case, the grader and the trial',cards([('Test case','Export a net-100 invoice with 21% VAT.'),('Grader','Parse the CSV and check that net, VAT and gross are 100, 21 and 121.'),('Trial','One fresh attempt with a recorded model, prompt, tools and environment.')]),'Evaluate the resulting artifact. A message saying “done” is not the outcome.','This is an illustrative task definition. Other cases cover zero VAT, rounding and CSV quoting. The grader can have a bug too; inspect it against known correct and incorrect outputs.'),5:s('Acceptance cases','Make the expected behavior explicit',table(['Case','Expected result'],[['Net 100.00; VAT 21%','VAT 21.00; gross 121.00'],['Net 100.00; VAT 0%','VAT 0.00; gross 100.00'],['Net 0.05; VAT 10%; half-up cents','VAT 0.01; gross 0.06'],['Customer name: ACME, Ltd','One customer field after CSV parsing']]),'For this exercise, round VAT half up to cents, then add it to net. The business rule must come from the task.','These exact examples are synthetic teaching fixtures, not universal tax advice. Use decimal arithmetic in the grader. The CSV test should parse fields, not merely search for a comma.'),6:s('Grading methods','Use the strongest practical check for each claim',cards([('Deterministic check','Parse CSV, assert values and run regression tests.'),('Written rubric','Assess explanation quality and completeness against named criteria.'),('Human calibration','Check ambiguous cases and compare model-judge scores with human decisions.')]),'A different judge model does not remove bias. Blind labels and vary answer order where practical.','A model judge is useful for subjective dimensions but can favor style, verbosity or familiar outputs. Treat grader disagreement as evidence to inspect, not automatic model failure.',theme='dark'),7:s('Repeated trials','One success answers a different question',code('Illustrative outcomes for one case: fail fail pass fail fail\n\nAt least one success in five attempts: yes\nAll five attempts successful: no\nObserved single-attempt success rate: 1 / 5'),'This small sample does not establish production reliability. Report task coverage, repeats and uncertainty.','Explain pass@k as probability of at least one success within k attempts and pass^k as probability all k succeed. This row illustrates the events, not a reliable estimate of either probability. Retries cost time and tokens.'),8:s('Trace evidence','Record the observable run',bul(['Inputs, configuration, tool requests, results and timestamps.','Final files or external state, check output and exit statuses.','Usage categories, retries, failures and any unavailable evidence.']),'Telemetry is not a full transcript, and neither guarantees access to hidden model reasoning.','Avoid promising every reasoning block. Capture what the harness and provider expose with appropriate redaction. The environment’s final artifact matters more than the agent’s description of it.',theme='dark'),9:s('Annotated trace','A repeated step is a question to investigate',table(['Observed step','What to ask'],[['Read calc.py; edit it; read it again','Did the second read inspect the changed code?'],['Repeat a failed tool call','Did the environment or arguments change?'],['Restate the plan after a handoff','Did this restore missing requirements?']]),'Label a step waste only after checking its purpose and effect.','Replaces the assertion that half an illustrative trace was waste. The counterfactual is whether omitting the step preserves correctness and reduces work.'),10:s('Telemetry versus transcripts','Use the right evidence for the question',cards([('Usage and event telemetry','Find cost, duration and tool-failure patterns across runs.'),('Transcript and artifacts','Explain a particular wrong result and inspect what actually changed.')]),link('https://code.claude.com/docs/en/monitoring-usage','Claude Code monitoring documentation')+' describes the available metrics and events.','Logging settings and tool support determine what is available. Do not assume a standard exporter captures all prompts, outputs and hidden reasoning.',theme='dark'),11:s('Results worksheet','Keep failed runs in the comparison',table(['Per trial','Record'],[['Identity','Case, variant, run number and versioned environment.'],['Outcome','Acceptance checks, rubric scores and evidence paths.'],['Work','Uncached input, cache writes/reads, output and retries.'],['Operational result','Time, total cost, review effort and error reason.']]),'Aggregate success rate and total spend over all trials. Do not report only successful attempts.','Use the same starting repository for each trial and prevent artifacts leaking between variants. Separate development cases from held-out checks.'),12:s('Grading exercise','Score two synthetic outputs',code('10 minutes — no model call needed\n\nA: net=100, VAT=21, gross=121 for BOTH 21% and 0% orders.\nB: correct totals for both; customer ACME, Ltd is unquoted.\n\nGrade against the four cases. Which outputs fail?\nWhat evidence is still missing?'),'Output: a scored worksheet with explanations. Neither candidate is ready to accept.','A fails zero VAT. B fails the comma-containing customer field. Rounding is untested in both, so mark unknown rather than inventing a pass. See exercise-materials.md for the synthetic CSV fixtures.',theme='dark'),13:s('Exercise debrief','A good report includes unknowns',table(['Check','A','B'],[['21% VAT totals','pass','pass'],['Zero VAT totals','fail','pass'],['Half-up rounding','not tested','not tested'],['CSV quoting','not tested','fail']]),'No measured speed or token-cost result exists for these synthetic outputs.','A single missing critical case is enough to block acceptance. The next experiment should exercise rounding and repair the known failures. Avoid choosing B simply because it has more passes; it still fails a requirement.'),15:eng.e[30],20:s('Local model memory','Active parameters are not the RAM requirement',bul(['Stored weights depend on total parameters, representation and quantization.','Inference also needs a KV cache, activations, runtime buffers and overhead.','Offloading can move weights to CPU memory or disk, trading memory for transfer time.']),'Approximate weight storage: parameters × bits per weight ÷ 8. This is a lower-bound estimate, not a fit guarantee.','For mixture-of-experts models, few parameters may be active per token while many expert weights still need storage. Example: 35 billion parameters at four bits is about 17.5 decimal GB before metadata and runtime overhead; it is not a three-billion-parameter memory footprint.',theme='dark'),22:s('Hardware experiment','Measure on the machine and task you intend to use',table(['Record','Why'],[['Model, quantization and runtime','Defines the actual workload and implementation.'],['Context size and concurrency','Changes KV cache and memory demand.'],['Peak memory and elapsed time','Reveals fit and practical responsiveness.'],['Acceptance results','Shows whether it did the task correctly.']]),'No model download or hardware benchmark is required for this talk.','This replaces an unconditional laptop-viability demo. Any optional rehearsal must record exact hardware and environment. Local inference still uses electricity, hardware and operator time.'),25:s('Local or hosted','Choose from constraints and observed results',cards([('Local may fit','You can meet the quality, latency and memory requirements in an approved local environment.'),('Hosted may fit','Its capability and operations meet your requirements, and the data path and commercial terms are acceptable.')]),'Inspect the whole workflow: local inference does not stop tools or telemetry from using the network.','A deployment decision needs real measurements and organization-specific requirements. A small active parameter count or benchmark headline is insufficient.',theme='dark'),27:s('Voice input','Review dictated requirements before execution',code('Spoken: “Export invoices without changing stored records.”\n\nCheck the transcription for:\n- negation: WITHOUT changing records\n- exact file names and amounts\n- scope and permission boundaries'),'A voice interface changes input convenience, not the acceptance checks.','Removes the unverified Hlas note and version-specific voice demo claims. Any available dictation tool can support this static example. No microphone or recorded run is required.'),30:s('Next experiment','Change one thing and keep the acceptance bar',bul(['Choose representative cases and calibrate the grader.','Compare variants on repeated, isolated trials.','Inspect failures, then keep the change only if the complete result improves.']),'Keep separate cases for the final check so prompt tuning does not simply memorize the test set.','The practical takeaway is an evaluation action, not allegiance to a model tier.',theme='dark'),31:sources([('Agent evaluation structure',EVAL),('Claude Code telemetry','https://code.claude.com/docs/en/monitoring-usage'),('Model loading and offloading','https://huggingface.co/docs/accelerate/usage_guides/big_modeling')])}
selection=s('Configuration worksheet','Record what you are comparing',table(['Layer','Record before running'],[['Model','Exact identifier, effort and generation settings.'],['Harness','Version, prompts, tools, permissions and retry logic.'],['Routing service','Provider selection, fallback behavior and data path.'],['Local runtime','Quantization, hardware, context and concurrency.']]),'A changed harness can change the result even with the same model.','Replaces the alternative-model catalogue with a reproducible comparison record. Published model cards and exact runtime docs belong with any actual experiment.')
prob=s('Repeated-run probabilities','The independence assumption matters',code('If each trial succeeds independently with probability p:\n\nP(at least one success in k trials) = 1 − (1 − p)^k\nP(all k trials succeed)            = p^k\n\nFor p = 0.8 and k = 3: 0.992 versus 0.512.'),'These are mathematical examples, not measured model results. Correlated failures can invalidate the simple model.','Estimate probabilities from appropriate repeated runs across representative cases. Shared state, identical systematic errors and adaptation between attempts can violate the assumptions.',theme='dark')
build('measuring-what-works','Measuring What Works',list(measure.items()),[(16,selection),(7,prob),(24,measure[20]),(28,measure[27])],{14:'Catalogue divider removed.',17:'Routing-provider claims replaced by configuration worksheet.',18:'Minimal-harness pricing claims replaced by configuration worksheet.',19:'Unqualified frontier-gap claim removed.',21:'Active-parameter inference corrected in main memory explanation.',23:'Empty local-demo recording replaced by hardware experiment.',26:'Closing divider removed.',29:'Generic habit list replaced by a concrete evaluation action.'})

# BEST PRACTICES: keep the attributed ideas, apply them to one verification example.
bp={1:cover('Claude<br>Best Practices','Practical lessons from Anthropic’s engineering posts, tested against your own work.','Advanced · daily Claude Code users'),2:s('Agenda','Start with three changes',cards([('Instructions','Remove conflicting or obsolete rules; preserve real constraints.'),('Verification','Make done depend on evidence tied to the task.'),('Measurement','Compare configurations by outcomes, cost and review effort.')]),'Skills, caching and delegation support these three habits.','Keep the practical outcome before the eight-topic catalogue. The sources are engineering reports, not guarantees for every repository.'),4:s('Simplifying prompts','Use the reported result as a reason to test',cards([('Reported by Anthropic','Its team removed over 80% of a system prompt for particular models without a measured drop on its coding evals.'),('Your next step','Remove one obsolete instruction group, then rerun your own acceptance cases.')]),link('https://claude.dev/blog/the-new-rules-of-context-engineering-for-claude-5-generation-models/','Source: context engineering, July 2026'),'This is a scoped report from Anthropic, not an instruction to delete eighty percent of every CLAUDE.md. Preserve constraints whose removal causes a meaningful failure.',theme='dark'),6:cost[19],7:s('Instruction audit','Find conflicts before adding another rule',code('Conflict in an illustrative project:\n“Never add comments.”\n“Document non-obvious tax rounding decisions.”\n\nReplacement:\n“Explain non-obvious rounding decisions near the code.”'),'Then check the task that originally required the rule.','The example is our adaptation, not a quote. Remove stale workarounds only when the original failure is understood and covered. Do not automatically trust an audit command to determine the correct policy.'),9:eng.e[52],11:s('Skill interface','Make the trigger and output specific',cards([('Trigger','“Verify changes to invoice totals or CSV export.”'),('Result','Findings with file references, check output and untested cases.')]),'Test one matching request and one unrelated request. Revise the description if discovery is unreliable.','A description aids discovery but is not a deterministic dispatch contract. Include a manual invocation path for important checks.',theme='dark'),12:s('Skill structure','Keep the core procedure short',code('invoice-check/\n  SKILL.md       trigger, steps, expected report\n  scripts/       deterministic parsing and checks\n  references/    rounding rules and exceptional cases'),'Load detail when useful. Review executable helpers and their permissions.','The skill is a folder, not just a wall of text. Preserve the specific gotcha in the relevant reference. A helper script can still be wrong; inspect and validate it.'),14:sub[25],15:eng.e[31],16:s('Cache tradeoffs','Preserve reuse when it serves the task',cards([('Avoid accidental churn','Keep stable instructions and tool definitions stable where practical.'),('Make necessary changes','Correct stale rules, change a failing configuration or compact when the task needs it.')]),'A cache hit is valuable only when the resulting work is useful.','This replaces the blanket rule against mid-session model and tool changes. Cache invalidation is a cost to measure, not a veto on needed corrections.',theme='dark'),17:s('Compaction','Preserve the state that explains the next step',code('Handoff or compaction checklist\nGoal and acceptance cases\nCurrent files and actual check results\nDecisions, failed approaches and unresolved questions\nPermission boundary and next action'),'A matching prefix can help reuse where supported. Verify the summary’s completeness separately.','Do not promise cache-safe compaction for every client or setting. Summarization changes what future calls can use even when earlier processing was cached.'),19:s('Effort comparison','Change one setting at a time',table(['Hold constant','Compare'],[['Task, starting files and acceptance cases','Supported effort settings for the same model.'],['Tools, permissions and budget','Successes, failures, time, usage and review effort.']]),'Record the exact settings; “high” is not necessarily equivalent across models or versions.','Remove the mixed model/effort benchmark table. More effort can change verification behavior, but the effect and optimum are task-specific.',theme='dark'),21:s('Build and verify','Treat “low build, high verify” as a hypothesis',cards([('Proposed workflow','Build with a lower-effort setting, then run a distinct review and verification phase.'),('Acceptance test','Compare it with one configuration under the same overall budget and rubric.')]),link('https://claude.dev/blog/spending-your-effort/','Source: Spending your effort')+' describes the author’s workflow and experiments.','This retains the useful practical suggestion without claiming it is the universal best default. The review phase needs actual checks, not only a request to think harder.'),22:eng.e[40],23:eng.e[30],27:s('Real verification','Ask for evidence tied to the changed behavior',code('Before calling the invoice fix done:\n1. Run the invoice acceptance cases.\n2. Inspect changed assertions and the final diff.\n3. Check the exported CSV values.\n4. Report commands, exit statuses, failures and gaps.'),'A syntax check cannot establish the VAT calculation. A command that never starts is not a passed test.','Use the smallest check that actually exercises the relevant behavior, then the required regression suite. Do not expand testing merely to generate more output.',theme='dark'),26:s('Progress and regression checks','Use one metric for improvement and a guardrail for damage',cards([('Improvement target','Reduce export latency on the same fixture and environment.'),('Regression guardrail','Keep VAT correctness, CSV shape and memory use within the accepted limits.')]),'Do not improve the score by weakening the workload or grader.','This replaces secondary sprint statistics with a concrete engineering example. The target can change intentionally, but changes must be reviewed and separated from performance claims.'),28:measure[6],29:s('Avoid overfitting','Keep some cases out of prompt tuning',bul(['Develop on cases that expose known failures.','Hold back different invoice variants for the final comparison.','Inspect grader mistakes and near-duplicate cases before celebrating a score.']),'A better development score is evidence to investigate, not proof of general improvement.','Retain the hillclimbing lesson without a long benchmark table. Repeat runs and preserve cases that protect against regressions.',theme='dark'),31:eng.e[25],32:s('Handoff','Separate durable task state from delegation',code('TASK STATE\nGoal; completed work; evidence; unresolved work; next check.\n\nHELPER TASK\nOne scoped question; relevant inputs; permitted actions;\nrequired findings with evidence and uncertainty.'),'A new worker reads the handoff, verifies the current state, then continues.','The prior slide mixed a session handoff with one-subagent-per-service instructions. They solve different problems. A task checklist can be stale; reconcile it with the files.'),33:s('Human decisions','Keep ownership of scope and acceptance',cards([('Scope','Decide what outcome and tradeoffs are worth pursuing.'),('Authority','Set which actions require approval and enforce access boundaries.'),('Acceptance','Review the result against requirements and user-visible behavior.')]),'Delegation moves work; it does not remove accountability.','Replace broad encouragement to be braver with explicit product and permission decisions.',theme='dark'),36:s('Two useful patterns','Use separate contexts for a clear reason',cards([('Investigate and combine','Independent questions; evidence-bearing returns; one integration owner.'),('Build and review','One worker produces a patch; a separate reviewer checks it against a rubric.')]),'A second agent can miss the same issue. Keep deterministic checks and final acceptance.','Two patterns are enough for this talk. Advanced pattern catalogues remain in the original baseline; do not imply model diversity automatically removes bias.'),38:s('Cost and containment','Two checks before adding workers',cards([('Will it help?','Estimate coordination and review effort; measure cost per accepted result.'),('What may it touch?','Configure filesystem, network and credential boundaries independently of context separation.')]),'Enforce budgets in the harness. A token budget written in a prompt is a request, not necessarily a hard cap.','Removes anecdotal token counts and separates cost control from security containment.',theme='dark'),40:s('Tool interface','Make tool outcomes easy to interpret',code('Invoice verifier result\nstatus: failed\ncase: zero VAT\nexpected_gross: 100.00\nactual_gross: 121.00\nevidence: test output and fixture path'),'Use clear inputs, bounded outputs and explicit errors. Improve the tool from observed failure traces.','This replaces a history of tool redesigns with a concrete interface. Structured fields make interpretation easier but do not guarantee correct model reasoning.'),41:s('Useful HTML output','Use an interactive view when it improves a decision',cards([('Compare','Show invoice variants side by side with the changed fields highlighted.'),('Choose and export','Let the reviewer record a decision and export the accepted specification.')]),'Plain text is enough for a short finding. Choose the format from the review task.','Keep the HTML-output idea as a useful option, not a universal replacement for Markdown. The main outcome is a reviewable decision, not an impressive UI.',theme='dark'),42:s('Hooks and extensions','Automate a specific control, then test it',bul(['Example: require the invoice check before an authorized release step.','Verify the hook’s actual event, inputs, failure behavior and scope.','Test allowed, denied and error cases in a disposable environment.']),'A hook is only as strong as its placement and implementation. '+link('https://code.claude.com/docs/en/hooks','Hooks reference'),'Replace unstable mods API code with a concrete outcome and current documentation. A prompt or hook alone is not a complete sandbox.'),44:s('Tomorrow','Start with one repeatable improvement',bul(['Remove one conflicting instruction and run its regression cases.','Save the invoice verification procedure as a small skill.','Measure the next completed task, including failures and review.']),'Keep the change only when the evidence supports it.','The close now returns to the opening three actions, not eight slogans.',theme='dark'),45:sources([('Context engineering lessons','https://claude.dev/blog/the-new-rules-of-context-engineering-for-claude-5-generation-models/'),('Effort experiments','https://claude.dev/blog/spending-your-effort/'),('Evaluation and hillclimbing','https://claude.dev/blog/automating-eval-design-and-hillclimbing/'),('Skills documentation',SKILLS)])}
# Preserve the baseline article bibliography in manageable reference pages.
bporiginal=subprocess.check_output(['git','show',BASE+':best-practices.html'],cwd=ROOT,text=True)
last=eng.SECTION.findall(bporiginal)[-1];articlelinks=re.findall(r'<a href="([^"]+)"[^>]*>(.*?)<span class="u">',last,re.S)
bpref=[(43,s('Command reference','Find the command in the installed version',table(['Need','Check'],[['Inspect session context and usage','Installed help for context and cost/usage commands.'],['Change model or effort','Supported settings for that client and model.'],['Manage skills, hooks and plugins','Current documentation and versioned configuration.']]),link('https://code.claude.com/docs/en/interactive-mode','Interactive-mode reference'),'Avoid keeping a copied command matrix that implies every command exists in every release. This reference points to the maintained documentation.'))]
for j in range(0,len(articlelinks),5):
 items=[(re.sub(r'<[^>]+>','',label),u) for u,label in articlelinks[j:j+5]]
 bpref.append((45 if j==0 else 0,sources(items,'Original article bibliography · April–October 2026. Retained for attribution; only claims used in the revision were refreshed.')))
# Attribution on every substantive slide: applied examples are explicitly ours.
for i,c in list(bp.items()):
 if i in [1,2,45]:continue
 if 'Source:' not in c and 'source:' not in c:
  if i in [4,6,7,9,11,12]:u=SKILLS if i in [9,11,12] else CONTEXT
  elif i in [14,15,16,17]:u=CACHE
  elif i in [19,21,22,23]:u='https://claude.dev/blog/spending-your-effort/'
  elif i in [26,27,28,29]:u=EVAL
  elif i in [31,32,33,36,38]:u=SUB
  else:u='https://code.claude.com/docs/en/hooks' if i==42 else CONTEXT
  c=c.replace('</div></section>',f'<p class="src reveal">Applied example · {link(u,"supporting documentation")}</p></div></section>')
 bp[i]=c
build('best-practices','Claude Best Practices',list(bp.items()),bpref,{5:'Six-shift table merged into instruction audit and verification skill.',10:'Duplicate gotcha example merged into verification skill.',18:'Effort divider removed.',20:'Secondary effort statistics replaced by controlled comparison.',24:'Evaluation divider removed.',25:'Sprint statistics replaced by concrete progress/guardrail example.',30:'Autonomy divider removed.',34:'Multi-agent divider removed.',35:'Failure claims converted into bounded tasks and two patterns.',37:'Prompt catalogue replaced by the two role patterns.',39:'Harness divider removed.'})

# WORKSHOP: shared corrected material + self-contained participant exercises.
work={1:cover('Working Smarter<br>with Agents','A half-day workshop: define, measure, improve and verify one workflow.','Workshop · developers'),2:s('Workshop route','Leave with five concrete artifacts',table(['Block','Time','Participant output'],[['Define and evaluate','50 min','Acceptance cases + scored worksheet'],['Cost and context','45 min','Usage sheet + revised instructions'],['Break','15 min',''],['Coordinate and package','55 min','Ticket contract + verification skill'],['Choose tools and next experiment','45 min','Comparison design + next action']]),'Total: 210 minutes. Includes discussion; live execution is optional.','Facilitator uses the self-contained invoice exercise. No paid accounts are required for the static route. With a runtime, use disposable copies and approved access. Keep the participant output visible in each block.'),49:measure[4],50:measure[5],51:measure[6],52:measure[7],53:measure[8],54:measure[9],56:measure[11],57:measure[12],58:measure[13],4:eng.e[29],6:eng.e[31],13:cost[13],15:eng.e[34],18:eng.e[50],19:cost[19],24:cost[24],25:cost[25],21:cost[21],22:eng.e[36],28:orc[4],31:orc[7],33:orc[9],34:orc[10],36:eng.e[24],38:orc[14],43:orc[19],41:eng.e[52],46:orc[22],47:eng.e[53],44:eng.e[57],60:orc[25],63:orc[28],65:orc[30],67:eng.e[30],72:measure[20],74:measure[22],75:s('Static hardware exercise','Estimate storage, then list what is missing',code('10 minutes — illustrative hardware scenario\n35B total parameters; 3B active per token; four-bit weights.\nWeight-only storage ≈ 35B × 4 / 8 = 17.5 GB.\n\nWould a machine with 16 GB available memory fit it?\nWhat could offloading change? What must you measure?'),'Output: a qualified feasibility note. Include KV cache, buffers, quantization overhead and speed.','The weight-only figure already exceeds sixteen decimal GB. Offloading may permit execution with weights elsewhere, but this does not prove acceptable latency or quality. No laptop benchmark result is claimed.',theme='dark'),77:measure[25],79:measure[27],80:s('Static voice exercise','Find the transcription error before sending',cards([('Intended request','“Export the invoices without changing stored records.”'),('Faulty transcript','“Export the invoices, changing stored records.”')]),'3 minutes: restore the missing boundary and state the acceptance check.','This replaces the sixth empty demo fallback. Participants can perform it by reading; no microphone, voice product or external service is required.'),82:s('Workshop close','Choose one experiment to take back',code('My task and acceptance cases:\nThe one change I will compare:\nWhat I will keep constant:\nEvidence I will record:\nBudget and stop condition:\nWho reviews the result:'),'Output: one experiment plan with a clear owner and review date.','Use the final discussion to check whether each participant has a feasible experiment. Do not require a model purchase, deployment or organization change to complete the workshop.',theme='dark'),83:sources([('Agent evaluation',EVAL),('Context engineering',CONTEXT),('Prompt caching',CACHE),('Skills',SKILLS),('MCP architecture',MCP)])}
